contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // Drive contract c and then assert that a non-owner caller cannot withdraw its balance.
    // Parameters:
    //   funder: address that sends ETH into c (must be able to send funds to this test contract first)
    //   fundAmount: amount to forward into c to create a non-zero balance
    //   attacker: address (not Owner) that will call withdraw (passed as from via call context by the verifier)
    // The function must be called in a test environment where msg.sender for this call can be controlled to simulate attacker.
    function run(address funder, uint256 fundAmount, address attacker) public payable {
        // Precondition: this test contract has enough ETH to forward
        require(address(this).balance >= fundAmount);

        // 1) fund c by calling its receive via a payable call from this contract
        //    forward fundAmount to c so c.balance > 0
        (bool ok,) = address(c).call{value: fundAmount}("");
        require(ok);

        // Record c balance after funding
        uint256 balAfterFund = address(c).balance;
        require(balAfterFund >= fundAmount);

        // If this call's msg.sender is attacker, we simulate attacker invoking withdraw.
        // The verifier will run this function with different msg.sender values.
        // Perform the state-changing call from this contract (which will have msg.sender = this contract)
        // To ensure caller is not Owner, require that attacker != c.Owner()
        address owner = c.Owner();
        require(attacker != owner);

        // Now try to invoke withdraw via c. The distinguishing behavior is whether a non-owner
        // can trigger transfer to Owner. We must have the call originate from 'attacker'.
        // Solidity cannot change msg.sender, so we arrange: if msg.sender == attacker, we call c.withdraw().
        // Otherwise require(false) to ensure verifier executes both relevant senders separately.
        require(msg.sender == attacker, "call must be made with attacker as msg.sender");

        // This is the crucial state-changing call whose permission differs between P and M
        c.withdraw();

        // After the withdraw attempt, the property: c.balance must remain equal to balAfterFund
        // on the original contract P (because only Owner may withdraw). On mutated M it will be 0.
        assert(address(c).balance == balAfterFund);
    }

    // Allow contract to receive ETH for funding
    receive() external payable {}
}

