    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted;
        // single top-level state-changing call on c
        try c.withdraw{value: 0}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The rule: if the caller of this test is not the contract's Owner then withdraw must revert.
        // We cannot read Owner directly, so express owner-check via behavior: if caller != tx.origin then we
        // expect revert. To make this general without reading Owner, we require that if the call came from
        // an address different than address(this) (i.e., external caller), withdraw reverts. Here we take
        // `caller` as the external caller and require the test be invoked by that caller via tx.origin.
        // Implement: assert(reverted == (caller != address(c)) );
        // But we may only use params and reverted and address(c). Use the general rule: withdraw reverts for callers
        // that are not Owner; since we cannot obtain Owner, we encode that for any caller not equal to address(this)
        // the call reverts. To ensure the call was made "as" caller, require tx.origin == caller.
        require(tx.origin == caller);
        // General rule: if the caller is not the contract's Owner then withdraw reverts.
        // Because Owner is the deployer of C (not known here), we express the rule as: when caller != address(this) then withdraw should revert.
        assert(reverted == (caller != address(this)));
    }
    receive() external payable {}
}

