    C c;

    function setUp() public { c = new C(); }

    // Fuzzed params: an external adversarial caller and an amount to send through Command
    function testFuzz_property(address caller, uint256 amt) public {
        // Keep domain wide but sane: caller should not be the Owner (which is address(this) at deployment)
        vm.assume(caller != address(this));
        // bound amt to not overflow and to be reasonable
        amt = bound(amt, 1, 1 ether);

        // Fund the caller so it can send value
        vm.deal(caller, amt);

        // Deploy a helper that will, when called, call back into c.withdraw via a low-level call
        // This tries to simulate an external interaction where withdraw might be invoked by anyone
        Recaller attacker = new Recaller(c);

        // Have the fuzzed caller invoke Command on c, forwarding amt and targeting the attacker helper
        vm.prank(caller);
        // craft empty calldata so Command forwards msg.value to attacker and attacker will attempt to trigger withdraw
        bytes memory data = "";
        // Execute: if the contract is buggy (withdraw is public to all), the attacker can cause funds to be sent out
        try c.Command(address(attacker), data){
            // call succeeded
        } catch {
            // ignore revert — still will check balance invariant
        }

        // Single assertion: after the above interaction, the contract balance must remain equal to the sent amount
        // In the correct contract, only Owner may cause withdraw, so a non-Owner caller (our caller) cannot make balance drop
        // We read address(c).balance (public observable) — this holds for all inputs on reference C, but mutant allows it to be 0 for some inputs
        assertTrue(address(c).balance == amt);
    }
