// Helper that, when called (via low-level call), will attempt to trigger c.withdraw by calling c.withdraw() from itself.
// This represents an external party that can be invoked via Command and will try to move funds out by calling withdraw on c.
contract Recaller {
    C immutable target;
    constructor(C _c){ target = _c; }

    // accept Ether forwarded by Command
    receive() external payable {
        // Try to call withdraw on the target. If the target restricts withdraw to Owner, this will revert or fail.
        // If the target is mutated (withdraw is public), this will succeed and drain the contract to Owner.
        // Use low-level call to avoid bubbling revert to the original Command caller.
        (bool ok, ) = address(target).call(abi.encodeWithSignature("withdraw()"));
        // ignore ok; behavior is observed by checking address(target).balance in the test
        ok; // silence unused warning
    }
}

