contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz parameters: depositor (address) and deposit amount
    function testFuzz_property(address depositor, uint256 amt) public {
        // keep depositor as a non-zero address
        vm.assume(depositor != address(0));
        // bound the amount to a practical range to avoid overflows in bookkeeping and to ensure vm.deal works
        amt = bound(amt, 0, 1 ether);

        // fund the depositor so they can send ETH to the contract
        vm.deal(depositor, amt);

        // depositor sends amt to the contract (using payable fallback/receive)
        vm.prank(depositor);
        (bool sent, ) = address(c).call{value: amt}("");
        require(sent);

        // ensure contract has the expected balance before withdraw
        // (this is a local require to ensure the scenario is meaningful to distinguish behavior)
        // we allow amt==0 as admissible input; in that case both contracts leave balance 0 and property holds

        // Owner is the deployer (this contract created c in setUp? No: setUp used new C() executed by this test contract)
        // The reference contract sets Owner = msg.sender at construction. Since setUp() ran in this contract, this test contract is Owner.

        // Call withdraw as the Owner (this test contract)
        // no need to vm.prank since this contract is Owner
        c.withdraw();

        // The reference C should have sent the entire balance out, leaving address(c).balance == 0 for every admissible input.
        // Mutant that transfers only half will leave a positive balance when amt>0, so the fuzzer can find such an input.
        assertTrue(address(c).balance == 0);
    }
}

